 subdivisions=[("Common peroneal nerve", "short head of biceps femoris (in the thigh, from the sciatic trunk), lateral sural cutaneous nerve"), ("Deep peroneal nerve", "tibialis anterior, extensor digitorum longus and brevis, extensor hallucis longus, peroneus tertius; first dorsal web space"), ("Superficial peroneal nerve", "peroneus longus and brevis (eversion); dorsum of the foot and lateral leg")],
