 exam=["Schirmer test", "Nasal mucosal dryness", "Sensation over the cheek (V2)"],
 pearls=["Reduced tearing on the side of a facial palsy means the lesion is proximal to the greater petrosal nerve, before the ganglion", "The pterygopalatine fossa is a crossroads for tumor spread from the nose, palate and sinuses toward the skull base"],
